mapper.select:
select * from prj_project_change_meeting_judge ppmj
WHERE 1=1

    and ppmj.project_meeting_id = #{projectMeetingId}

select ppmj.project_meeting_id, ppmj.change_req_id, ppmj.judge_user_allocation_id, res.`NAME` judge_user_allocation_id_n, ppmj.judge_approve_result, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = ppmj.judge_approve_result and scb.CODE = 'PRJ.DIRECTOR_APPROVAL_RESULT' ) as JUDGE_APPROVE_RESULT_N, ppmj.judge_approve_comments, ppmj.judge_user_id, ppmj.director_flag, ppmj.absence_flag, ppmj.process_instance_id, ppmj.approved_time, res.unit_name department_name, res.position_name department_position, ppmj.project_meeting_judge_id from prj_project_change_meeting_judge ppmj, (SELECT fee.employee_code, fee. NAME, fn.unit_id, fn.unit_name, fop.position_id, fop.position_name, fc.company_short_name, sua.allocation_id, sua.user_id, fc.company_id FROM fnd_employee_assigns fea LEFT JOIN fnd_employee fee ON fea.employee_id = fee.employee_id LEFT JOIN fnd_org_unit fn ON fn.unit_id = fea.unit_id LEFT JOIN fnd_org_position fop ON fop.position_id = fea.position_id LEFT JOIN fnd_company fc ON fc.company_id = fea.company_id LEFT JOIN sys_user_allocation sua ON sua.employee_assign_id = fea.employee_assign_id ) res
res.allocation_id = ppmj.judge_user_allocation_id
and ppmj.project_meeting_id = #{projectMeetingId}
and ppmj.project_meeting_judge_id = #{projectMeetingJudgeId}
and ppmj.change_req_id = #{changeReqId}
and ppmj.judge_user_id = #{judgeUserId}
and ppmj.process_instance_id = #{processInstanceId}

select ppmj.*,(select scvb.MEANING
from sys_code_value_b scvb, sys_code_b scb
where scvb.CODE_ID = scb.CODE_ID
and scvb.VALUE = ppmj.judge_approve_result
and scb.CODE = 'PRJ.DIRECTOR_APPROVAL_RESULT'
) as JUDGE_APPROVE_RESULT_N
from prj_project_change_meeting_judge ppmj

    ppmj.project_meeting_id = #{projectMeetingId}

        and ppmj.project_meeting_judge_id = #{projectMeetingJudgeId}


        and ppmj.change_req_id = #{changeReqId}


        and ppmj.judge_user_id = #{judgeUserId}


        and ppmj.process_instance_id = #{processInstanceId}
